import{_ as a,o,c as t,a2 as i}from"./chunks/framework.Bum8orMG.js";const h=JSON.parse('{"title":"Roadmap","description":"What is planned for KatanaKit. Contributions welcome.","frontmatter":{"title":"Roadmap","description":"What is planned for KatanaKit. Contributions welcome."},"headers":[],"relativePath":"guides/roadmap.md","filePath":"guides/roadmap.md","lastUpdated":1791028743000}'),d={name:"guides/roadmap.md"};function r(c,e,s,n,l,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<p>A living list of what is planned for KatanaKit (<code>katanakit-js</code>). Contributions are welcome — pick something and open a pull request.</p><p>Legend: <code>[x]</code> done · <code>[ ]</code> planned.</p><h2 id="shipped-as-of-6-2-0" tabindex="-1">Shipped (as of 6.2.0) <a class="header-anchor" href="#shipped-as-of-6-2-0" aria-label="Permalink to &quot;Shipped (as of 6.2.0)&quot;">​</a></h2><h3 id="architecture-and-packaging" tabindex="-1">Architecture and packaging <a class="header-anchor" href="#architecture-and-packaging" aria-label="Permalink to &quot;Architecture and packaging&quot;">​</a></h3><ul><li>[x] Hexagonal reorganization into <code>types/</code>, <code>core/services/</code>, <code>infrastructure/</code>, <code>adapters/</code>, <code>config/</code>.</li><li>[x] Pure ESM: relative imports with explicit <code>.js</code> extensions, <code>module: nodenext</code>, <code>&quot;type&quot;: &quot;module&quot;</code> and an <code>exports</code> map with subpaths (<code>katanakit-js/adapters/express</code>, <code>katanakit-js/adapters/nuxt</code>).</li><li>[x] <code>use*</code> method convention across every service (only <code>getInstance()</code> is exempt).</li><li>[x] Destructured, tree-shakeable exports from Singleton facades.</li><li>[x] Single source of truth for contracts and domain types in <code>src/types/</code>.</li><li>[x] No side effects on import; SSR-safe infrastructure adapters.</li><li>[x] Removed TypeScript errors, import-time side effects and duplicate types.</li><li>[x] Dependency restructure: only <code>@js-temporal/polyfill</code> as a runtime dependency; <code>express</code>, <code>cors</code>, <code>dotenv</code> and <code>vue</code> as optional peer dependencies.</li><li>[x] Package renamed for publication as <code>katanakit-js</code> (previously developed as <code>katanakit-dev</code>).</li></ul><h3 id="services-and-adapters" tabindex="-1">Services and adapters <a class="header-anchor" href="#services-and-adapters" aria-label="Permalink to &quot;Services and adapters&quot;">​</a></h3><ul><li>[x] Core services: HTTP client, logger, formatter, converter, errors, generator, dates (Temporal), geometry, timing, data/system utilities and the reactive signals kernel.</li><li>[x] Infrastructure adapters: DOM, storage, viewport, sensors, observer (+ lazy loader), worker (+ pools) and theme.</li><li>[x] Astro adapter (<code>AstroService</code>) for <code>getStaticPaths</code>.</li><li>[x] RSS service (<code>RssService</code>) with raw XML generation and Astro <code>GET</code> endpoints — no external dependencies.</li><li>[x] Site config (<code>SiteConfig</code>/<code>siteConfig</code>) and SEO module (<code>useHeadTags</code>, <code>useGenerateMetaTags</code>, <code>useTitle</code>, <code>useRssHeadLink</code>).</li><li>[x] Nuxt adapter (<code>katanakit-js/adapters/nuxt</code>): <code>useUnwrap</code>, <code>useSafeResponse</code>, <code>useEventResponse</code>.</li><li>[x] Vue adapter (<code>katanakit-js/adapters/vue</code>): <code>useRequest</code> composable (<code>data</code>, <code>error</code>, <code>loading</code>, <code>refetch</code>).</li><li>[x] Express reference server (<code>katanakit-js/adapters/express</code>) with CORS restriction defaults and hardened headers.</li><li>[x] Worker pool concurrency fixed by correlating tasks with a <code>taskId</code> echo.</li><li>[x] <code>useEncrypt</code> generates a random salt when none is provided.</li></ul><h3 id="quality-and-tooling" tabindex="-1">Quality and tooling <a class="header-anchor" href="#quality-and-tooling" aria-label="Permalink to &quot;Quality and tooling&quot;">​</a></h3><ul><li>[x] Vitest suite (36+ files, 270+ tests) with the <code>@/</code> alias; jsdom coverage for the UI kit foundations.</li><li>[x] ESLint gate (<code>check</code> = eslint + <code>tsc6</code> typecheck + vitest; <code>fix</code> auto-fixes).</li><li>[x] Releases through GitHub Actions with npm OIDC trusted publishing (<code>.github/workflows/release.yml</code>) plus a local <code>bun run release</code> fallback.</li><li>[x] English documentation: README, Getting Started, Architecture, API Reference, Roadmap, CONTRIBUTING, SECURITY, CHANGELOG.</li><li>[x] Security fixes applied: URL scheme validation, DOM <code>on*</code> attribute block, JSON-LD <code>&lt;/script&gt;</code> escaping, worker cleanup, generic server errors.</li><li>[x] CI pipeline (GitHub Actions) running <code>check</code>, <code>build</code> and <code>examples:check</code> on push/PR to <code>main</code> and <code>dev</code>, plus a docs deploy workflow to Cloudflare.</li><li>[x] <code>QueryClient</code> (TanStack Query Core): cache with GC, stale-while-revalidate, retry with backoff, deduplication, invalidation and prefetch.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>[ ] HTTP client: request interceptors and per-request cancellation plumbing in <code>FetchApiManager</code> (the query layer already forwards <code>AbortSignal</code>).</li><li>[ ] Reactive: automatic dependency tracking for <code>useCreateEffect</code>/<code>useCreateMemo</code> (today signals are listed explicitly).</li><li>[ ] Structured/JSON logger strategy.</li><li>[ ] Add Vitest coverage reporting to CI.</li></ul><h2 id="later" tabindex="-1">Later <a class="header-anchor" href="#later" aria-label="Permalink to &quot;Later&quot;">​</a></h2><ul><li>[ ] UI kit (Katana UI): foundations shipped (button, input, card, badge, alert); shells, blocks, layouts and app pages remain. See the <a href="./../ui-kit/roadmap">UI Kit roadmap</a>.</li><li>[ ] Deno / Cloudflare Workers compatibility pass.</li><li>[ ] More geometry (3D solids) and unit-system conversions.</li><li>[ ] i18n and relative-time output for <code>DatesService.useDiff</code>.</li><li>[ ] E2E tests for the Express adapter.</li><li>[ ] AbortController support in <code>useInterval</code>/timeout helpers.</li></ul>',13)])])}const f=a(d,[["render",r]]);export{h as __pageData,f as default};
